23	
24	const MAX_DIMENSION = 140;
25	
26	const DEVICE_HEIGHT = Dimensions.get("window").height;
27	
28	const isVideo = (asset: Asset) => asset.type?.startsWith("video/");
29	
30	const handleImageSize = (asset: Asset) => {
31	  const originalWidth = asset.width ?? 0;
32	  const originalHeight = asset.height ?? 0;
33	  const scaleRatio = Math.min(
34	    MAX_DIMENSION / originalWidth,
35	    MAX_DIMENSION / originalHeight,
36	    1,
37	  );
38	  const targetWidth = Math.round(originalWidth * scaleRatio);
39	  const targetHeight = Math.round(originalHeight * scaleRatio);
40	
41	  return { width: targetWidth, height: targetHeight };
42	};
43	
44	export const SendImages: React.FC<
45	  NativeStackScreenProps<Routes, "sendImages">
46	> = ({ route, navigation }) => {
47	  const { roomId, images } = route.params;
48	  const [currentMedia, setCurrentMedia] = useState(images);
49	  const [currentMediaIndex, setCurrentMediaIndex] = useState(0);
50	  const [isSending, setIsSending] = useState(false);
51	  // Store captions for each media item by index
52	  const [captions, setCaptions] = useState<Record<number, string>>({});
53	  const activeMedia = useMemo(() => {
54	    return currentMedia[currentMediaIndex];
55	  }, [currentMedia, currentMediaIndex]);
56	  const isVertical = useMemo(() => {
57	    if (!activeMedia) return false;
58	    return (
59	      handleImageSize(activeMedia).width < handleImageSize(activeMedia).height
60	    );
61	  }, [activeMedia]);
62	
63	  const handleSendMedia = async () => {
64	    try {
65	      setIsSending(true);
66	      const tasks = currentMedia.map(async (asset, index) => {
67	        if (!asset?.uri) {
68	          return Promise.reject(new Error("No uri found"));
69	        }
70	
71	        const caption = captions[index];
72	        await TimelineService.sendMedia(roomId, asset, caption);
73	      });
74	
75	      const results = await Promise.allSettled(tasks);
76	      const failures = results.filter((r) => r.status === "rejected");
77	      if (failures.length) {
78	        failures.forEach((failure) => {
79	          console.error(failure.reason);
80	        });
81	        throw new Error("Failed to send some media");
82	      }
83	      navigation.goBack();
84	    } catch (error) {
85	      console.error(error);
86	      offlineToastHelper("Failed to send media");
87	    } finally {
88	      setIsSending(false);
89	    }
90	  };
91	
92	  const handleImagePress = (index: number) => {
93	    if (index === currentMediaIndex) {
94	      const newImages = currentMedia.filter((_, i) => i !== index);
95	      setCurrentMedia(newImages);
96	      setCurrentMediaIndex(Math.min(currentMediaIndex, newImages.length - 1));
97	      // Remove caption for deleted media and reindex remaining captions
98	      const newCaptions: Record<number, string> = {};
99	      Object.keys(captions).forEach((key) => {
100	        const oldIndex = Number.parseInt(key, 10);
101	        if (oldIndex < index) {
102	          newCaptions[oldIndex] = captions[oldIndex];
103	        } else if (oldIndex > index) {
104	          newCaptions[oldIndex - 1] = captions[oldIndex];
105	        }
106	      });
107	      setCaptions(newCaptions);
108	      return;
109	    }
110	
111	    setCurrentMediaIndex(index);
112	  };
113	
114	  const handleCaptionChange = (text: string) => {
115	    setCaptions((prev) => ({
116	      ...prev,
117	      [currentMediaIndex]: text,
118	    }));
119	  };
120	
121	  return (
122	    <ScreenLayout background={Colors.blackMinus1}>
123	      {isSending && <Loading text="Sending media..." />}
124	      <GoBackHeader isClose />
125	      <KeyboardAvoidingView
126	        style={{ flex: 1 }}
127	        behavior="padding"
128	        keyboardVerticalOffset={0}
129	      >
130	        <Block flex={1} align="center" justify="center">
131	          <Block
132	            height={DEVICE_HEIGHT - 400} //Estimated height of the keyboard
133	            overflow="hidden"
134	            margins={{ marginBottom: "auto" }}
135	          >
136	            {isVideo(activeMedia) ? (
137	              <Video
138	                source={{ uri: activeMedia.uri }}
139	                style={{
140	                  height: isVertical ? "100%" : "auto",
141	                  width: isVertical ? "auto" : "100%",
142	                  aspectRatio:
143	                    handleImageSize(activeMedia).width /
144	                    handleImageSize(activeMedia).height,
145	                }}
146	                resizeMode="contain"
147	                controls
148	                paused={false}
149	              />
150	            ) : (
151	              <Image
152	                source={{ uri: activeMedia.uri }}
153	                width={handleImageSize(activeMedia).width}
154	                height={handleImageSize(activeMedia).height}
155	                style={{
156	                  height: isVertical ? "100%" : "auto",
157	                  width: isVertical ? "auto" : "100%",
158	                  aspectRatio:
159	                    handleImageSize(activeMedia).width /
160	                    handleImageSize(activeMedia).height,
161	                }}
162	              />
163	            )}
164	          </Block>
165	
166	          <Block
167	            flex={1}
168	            justify="flex-end"
169	            absolute
170	            width="100%"
171	            offsets={{ bottom: 0 }}
172	            gap={20}
173	          >
174	            <Block width="100%" gap={4} align="flex-start">
175	              {currentMedia.length > 1 && (
176	                <FlatList
177	                  contentContainerStyle={styles.container}
178	                  data={currentMedia}
179	                  horizontal
180	                  showsHorizontalScrollIndicator={false}
181	                  renderItem={({ item, index }) => (
182	                    <Button.Wrapper onPress={() => handleImagePress(index)}>
183	                      {isVideo(item) ? (
184	                        <Video
185	                          source={{ uri: item.uri }}
186	                          style={styles.media}
187	                          resizeMode="cover"
188	                          paused
189	                        />
190	                      ) : (
191	                        <Image
192	                          source={{ uri: item.uri }}
193	                          width={78}
194	                          height={78}
195	                          resizeMode="cover"
196	                          style={styles.media}
197	                        />
198	                      )}
199	                      {isVideo(item) && (
200	                        <Block
201	                          absolute
202	                          offsets={{ top: 0, left: 0 }}
203	                          width="100%"
204	                          height="100%"
205	                          align="center"
206	                          justify="center"
207	                          pointerEvents="none"
208	                        >
209	                          <Block
210	                            width={20}
211	                            height={20}
212	                            background={Colors.white50}
213	                            border={{ borderRadius: 10 }}
214	                            align="center"
215	                            justify="center"
216	                          >
217	                            <Text style={{ fontSize: 10 }}>▶</Text>
218	                          </Block>
219	                        </Block>
220	                      )}
221	                      {index === currentMediaIndex && (
222	                        <Block
223	                          absolute
224	                          offsets={{ top: 0, left: 0 }}
225	                          width="100%"
226	                          height="100%"
227	                          background={Colors.white50}
228	                          border={{
229	                            borderRadius: 4,
230	                            borderWidth: 1,
231	                            borderColor: Colors.white,
232	                          }}
233	                          align="center"
234	                          justify="center"
235	                        >
236	                          <Block
237	                            height={48}
238	                            width={48}
239	                            align="center"
240	                            justify="center"
241	                            background={Colors.white50}
242	                            border={{ borderRadius: 999 }}
243	                          >
244	                            <Image
245	                              source={require("assets/icons/trash.png")}
246	                              width={24}
247	                              height={24}
248	                              tintColor={Colors.black}
249	                            />
250	                          </Block>
251	                        </Block>
252	                      )}
253	                    </Button.Wrapper>
254	                  )}
255	                />
256	              )}
257	            </Block>
258	
259	            <Block
260	              width="100%"
261	              flexDirection="row"
262	              gap={8}
263	              background={Colors.blackMinus1}
264	              align="flex-end"
265	            >
266	              <Block flex={1}>
267	                <Input
268	                  placeholder="Caption"
269	                  value={captions[currentMediaIndex] || ""}
270	                  autoCapitalize="sentences"
271	                  onChangeText={handleCaptionChange}
272	                  multiline
273	                />
274	              </Block>
275	              <Button.Wrapper onPress={handleSendMedia}>
276	                {currentMedia.length > 1 && (
277	                  <Block
278	                    absolute
279	                    offsets={{ top: -6, right: -6 }}
280	                    zIndex={2}
281	                    height={24}
282	                    width={24}
283	                    align="center"
284	                    justify="center"
285	                    background={Colors.primary}
286	                    border={{
287	                      borderRadius: 999,
288	                      borderWidth: 1,
289	                      borderColor: Colors.white20,
290	                    }}
291	                  >
292	                    <Text size={TextSize.small}>{currentMedia.length}</Text>
