294	                )}
295	                <Block
296	                  height={48}
297	                  width={48}
298	                  align="center"
299	                  justify="center"
300	                  background={Colors.primary}
301	                  border={{
302	                    borderRadius: 999,
303	                    borderWidth: 1,
304	                    borderColor: Colors.white20,
305	                  }}
306	                >
307	                  <Image
308	                    source={require("assets/icons/paper-plane-right.png")}
309	                    width={24}
310	                    height={24}
311	                  />
312	                </Block>
313	              </Button.Wrapper>
314	            </Block>
315	          </Block>
316	        </Block>
317	      </KeyboardAvoidingView>
318	    </ScreenLayout>
319	  );
320	};
321	
322	const styles = StyleSheet.create({
323	  container: {
324	    gap: 4,
325	  },
326	  media: {
327	    width: 78,
328	    height: 78,
329	    borderRadius: 4,
330	  },
331	  button: {
332	    marginTop: "auto",
333	  },
334	  size: {
335	    width: 78,
